    if (($c.util.getComponent('AKCKwd').getValue() == null ? '' : String($c.util.getComponent('AKCKwd').getValue())) !== '') {
        $c.util.getComponent("dma_fnDownloadReq").set("searchCorpName", $c.util.getComponent('AKCKwd').getValue());
        fnAKCKwdSearchCorpNamefnAKCKwdSearchCorpName();
    } else {
        await scwin.fnSearch();
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.setCorpInfo
 * @author Inswave
 * @date 2026. 09. 29
 * @param isurCd kisComCd ipt_repIsuSrtCd comNm comAbbrv isurSymbl fssUnqNo
 * @returns
 * @hidden N
*/
scwin.setCorpInfo = function (isurCd, kisComCd, ipt_repIsuSrtCd, comNm, comAbbrv, isurSymbl, fssUnqNo) {
    /* sdd-asis-lifecycle:begin setCorpInfo — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let str = "";
    str += "isurCd : " + isurCd + "\n";
    str += "kisComCd : " + kisComCd + "\n";
    str += "repIsuSrtCd : " + ipt_repIsuSrtCd + "\n";
    str += "comNm : " + comNm + "\n";
    str += "comAbbrv : " + comAbbrv + "\n";
    str += "isurSymbl : " + isurSymbl + "\n";
    str += "fssUnqNo : " + fssUnqNo + "\n";
    $c.util.getComponent('AKCKwd').setValue(comAbbrv);
    $c.util.getComponent("dma_fnDownloadReq").set("repIsuSrtCd", "A" + ipt_repIsuSrtCd);
    $c.util.getComponent("dma_fnDownloadReq").set("chkOrgData", ipt_repIsuSrtCd);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.changeSelYear
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.changeSelYear = function () {
    /* sdd-asis-lifecycle:begin changeSelYear — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const selYear = $("#searchForm").find("select[name=selYear]").val();
    (($c.util.getComponent('slc_selYearCnt')) && ($c.util.getComponent('slc_selYearCnt')).removeAll ? ($c.util.getComponent('slc_selYearCnt')).removeAll() : (($c.util.getComponent('slc_selYearCnt')) && ($c.util.getComponent('slc_selYearCnt')).setValue ? ($c.util.getComponent('slc_selYearCnt')).setValue('') : void 0));
    if (selYear === '2011') {
        $c.util.getComponent('slc_selYearCnt').addItem("2", "2");
        $c.util.getComponent('slc_selYearCnt').addItem("1", "1");
    } else {
        if (selYear === '2010') {
            $c.util.getComponent('slc_selYearCnt').addItem("1", "1");
        } else {
            $c.util.getComponent('slc_selYearCnt').addItem("3", "3");
            $c.util.getComponent('slc_selYearCnt').addItem("2", "2");
            $c.util.getComponent('slc_selYearCnt').addItem("1", "1");
        }
    }
    /* sdd-asis-lifecycle:end */
};
